# Shared by the demo scripts: read a value from .env without printing it.
# The UI passwords are random per installation (generated by start.sh / start.ps1).
# Usage (after cd to the repo root):  source scripts/lib/env.sh; env_value ADMIN_PASSWORD
env_value() {
  [ -f .env ] || { echo "No .env: run ./start.sh first" >&2; return 1; }
  grep -E "^$1=" .env | head -1 | cut -d= -f2- | tr -d '\r'
}
